def investigate(context, acquire):
    hist = acquire("history")

    def simulate(mode, chan, trig, actions):
        committed = {}
        pending = {"main": {}, "other": {}}
        in_txn = {"main": False, "other": False}
        changes_main = 0
        total_main = 0
        total_other = 0

        def visible(conn, k):
            if k in pending[conn]:
                return pending[conn][k]
            return committed.get(k, None)

        def flush(conn):
            for k, v in pending[conn].items():
                if v is None:
                    committed.pop(k, None)
                else:
                    committed[k] = v
            pending[conn] = {}

        def do_write(conn, key, value, is_put):
            nonlocal changes_main, total_main, total_other
            cur = visible(conn, key)
            d = 0
            t = 0
            if is_put:
                if mode == "ignore":
                    if cur is None:
                        d = 1
                        if trig:
                            t = 1
                        pending[conn][key] = value
                elif mode == "replace":
                    if cur is None:
                        d = 1
                        if trig:
                            t = 1
                        pending[conn][key] = value
                    else:
                        d = 1
                        if trig:
                            t = 1
                        pending[conn][key] = value
                        total_main += 1
                        total_other += 0
                elif mode == "upsert":
                    d = 1
                    if trig:
                        t = 1
                    pending[conn][key] = value
            else:
                if cur is not None:
                    d = 1
                    if trig:
                        t = 1
                    pending[conn][key] = value
            if conn == "main":
                changes_main = d
                total_main += d + t
            else:
                total_other += d + t
            if not in_txn[conn]:
                flush(conn)

        def do_delete(conn, key):
            nonlocal changes_main, total_main, total_other
            cur = visible(conn, key)
            d = 0
            t = 0
            if cur is not None:
                d = 1
                if trig:
                    t = 1
                pending[conn][key] = None
            if conn == "main":
                changes_main = d
                total_main += d + t
            else:
                total_other += d + t
            if not in_txn[conn]:
                flush(conn)

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                in_txn[conn] = True
            elif op == "commit":
                flush(conn)
                in_txn[conn] = False
            elif op == "rollback":
                pending[conn] = {}
                in_txn[conn] = False
            elif op == "put":
                do_write(conn, act["key"], act["value"], True)
            elif op == "update":
                do_write(conn, act["key"], act["value"], False)
            elif op == "delete":
                do_delete(conn, act["key"])

        if chan == "changes":
            ch = changes_main
        elif chan == "total_main":
            ch = total_main
        else:
            ch = total_main + total_other
        cnt = len(committed)
        sm = 0
        for v in committed.values():
            sm += v
        return (ch, cnt, sm)

    modes = ["ignore", "replace", "upsert"]
    chans = ["changes", "total_main", "total_both"]
    trigs = [False, True]

    candidates = []
    for m in modes:
        for c in chans:
            for t in trigs:
                ok = True
                for rec in hist:
                    r = simulate(m, c, t, rec["actions"])
                    obs = rec["observed"]
                    if r[0] != obs["channel"] or r[1] != obs["committed_count"] or r[2] != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((m, c, t))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for (m, c, t) in candidates:
        r = simulate(m, c, t, actions)
        if goal == "channel":
            vals.add(r[0])
        elif goal == "committed_count":
            vals.add(r[1])
        elif goal == "committed_sum":
            vals.add(r[2])
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

